"""Array-level comparison of ksched_split.parse_kernel (sequential) and ksched_parse_parallel.parse_kernel_parallel on one
session: every returned table as a multiset of rows (order-free), the ctx map as a dict. Prints sizes, timings and the first
differing rows. usage: ksched_parse_compare.py <session_dir> [--tz TZ] [--only parallel|sequential]"""
import argparse, os, sys, time
import numpy as np
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'postprocess'))
from ingest_pg import DEFAULT_TZ
import ksched_split as K
from ksched_parse_parallel import parse_kernel_parallel

ap = argparse.ArgumentParser(); ap.add_argument('session_dir'); ap.add_argument('--tz', default=DEFAULT_TZ); ap.add_argument('--only', default=None)
a = ap.parse_args()
res = {}
for name, fn in (('parallel', lambda: parse_kernel_parallel(a.session_dir, a.tz)), ('sequential', lambda: K.parse_kernel(a.session_dir, a.tz))):
    if a.only and a.only != name: continue
    t = time.time(); res[name] = fn(); print(f"{name}: {time.time() - t:.0f} s", flush=True)
if len(res) < 2: sys.exit(0)
P, S = res['parallel'], res['sequential']
names = ['on', 'off', 'ctx', 'wk', 'fx', 'gp']
def rows(cols):
    cols = [np.asarray(c) for c in cols]
    if len(cols[0]) == 0: return np.zeros((0, len(cols)), np.int64)
    m = np.stack([c.astype(np.int64) for c in cols], axis=1)
    return m[np.lexsort(tuple(m[:, i] for i in range(m.shape[1] - 1, -1, -1)))]
ok = True
for i, nm in enumerate(names):
    if nm == 'ctx':
        d1, d2 = P[i], S[i]; miss = set(d2) - set(d1); extra = set(d1) - set(d2); diff = [k for k in set(d1) & set(d2) if d1[k] != d2[k]]
        print(f"ctx: parallel {len(d1)} sequential {len(d2)}; missing {len(miss)} extra {len(extra)} differing {len(diff)}" + (f" e.g. {list(diff)[:3]} -> {[(d1[k], d2[k]) for k in list(diff)[:3]]}" if diff else ''))
        ok &= not (miss or extra or diff); continue
    r1, r2 = rows(P[i]), rows(S[i])
    same = r1.shape == r2.shape and np.array_equal(r1, r2)
    print(f"{nm}: parallel {len(r1)} rows, sequential {len(r2)} rows -> {'identical' if same else 'DIFFERENT'}")
    if not same:
        ok = False
        s1 = {tuple(x) for x in r1.tolist()}; s2 = {tuple(x) for x in r2.tolist()}
        only_p = sorted(s1 - s2)[:6]; only_s = sorted(s2 - s1)[:6]
        print(f"   rows only in parallel: {len(s1 - s2)} e.g. {only_p}")
        print(f"   rows only in sequential: {len(s2 - s1)} e.g. {only_s}")
print('PARSE COMPARE', 'IDENTICAL' if ok else 'DIFFERENT')
